31: const startBroadcast = async (
32:     room: Room,
33:     client: MatrixClient,
34:     recordingsStore: VoiceBroadcastRecordingsStore,
35: ): Promise<VoiceBroadcastRecording> => {
36:     const { promise, resolve, reject } = defer<VoiceBroadcastRecording>();
37: 
38:     const userId = client.getUserId();
39: 
40:     if (!userId) {
41:         reject("unable to start voice broadcast if current user is unknown");
42:         return promise;
43:     }
44: 
45:     let result: ISendEventResponse | null = null;
46: 
47:     const onRoomStateEvents = () => {
48:         if (!result) return;
49: 
50:         const voiceBroadcastEvent = room.currentState.getStateEvents(VoiceBroadcastInfoEventType, userId);
51: 
52:         if (voiceBroadcastEvent?.getId() === result.event_id) {
53:             room.off(RoomStateEvent.Events, onRoomStateEvents);
54:             const recording = new VoiceBroadcastRecording(voiceBroadcastEvent, client);
55:             recordingsStore.setCurrent(recording);
56:             recording.start();
57:             resolve(recording);
58:         }
59:     };
60: 
61:     room.on(RoomStateEvent.Events, onRoomStateEvents);
62: 
63:     // XXX Michael W: refactor to live event
64:     result = await client.sendStateEvent(
65:         room.roomId,
66:         VoiceBroadcastInfoEventType,
67:         {
68:             device_id: client.getDeviceId(),
69:             state: VoiceBroadcastInfoState.Started,
70:             chunk_length: getChunkLength(),
71:         } as VoiceBroadcastInfoEventContent,
72:         userId,
73:     );
74: 
75:     return promise;
76: };
