describe("pruneClientInformation", () => {
    let client: MatrixClient;
    const prefix = "io.element.matrix_client_information.";

    const accountData = {
        [`${prefix}AAA`]: new MatrixEvent({ type: `${prefix}AAA`, content: { name: "Element" } }),
        [`${prefix}BBB`]: new MatrixEvent({ type: `${prefix}BBB`, content: { name: "Element" } }),
        [`${prefix}CCC`]: new MatrixEvent({ type: `${prefix}CCC`, content: { name: "Element" } }),
        "m.other": new MatrixEvent({ type: "m.other", content: {} }),
    };

    beforeEach(() => {
        client = getMockClientWithEventEmitter({
            ...mockClientMethodsUser(),
            getAccountData: jest.fn().mockReturnValue(accountData),
            deleteAccountData: jest.fn(),
        });
    });

    it("deletes entries for devices that no longer exist", () => {
        pruneClientInformation(["AAA", "CCC"], client);
        expect(client.deleteAccountData).toHaveBeenCalledTimes(1);
        expect(client.deleteAccountData).toHaveBeenCalledWith(`${prefix}BBB`);
    });

    it("deletes nothing when the device list is empty", () => {
        pruneClientInformation([], client);
        expect(client.deleteAccountData).not.toHaveBeenCalled();
    });
});

